import numpy as np
from scipy import stats
from sklearn.metrics import roc_auc_score
from sklearn.linear_model import LogisticRegression
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers based on t-statistics and AUC
    t_stats = []
    auc_scores = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            # For clinical features, use Welch's t-test
            y0 = feats.x[feats.y == 0, i]
            y1 = feats.x[feats.y == 1, i]
            t_stat, _ = stats.ttest_ind(y0, y1, equal_var=False)
            t_stats.append(abs(t_stat))
        else:
            # For other features, compute difference in means
            y0_mean = np.mean(feats.x[feats.y == 0, i])
            y1_mean = np.mean(feats.x[feats.y == 1, i])
            t_stats.append(abs(y1_mean - y0_mean))

        # Compute AUC for this feature
        auc = roc_auc_score(feats.y, feats.x[:, i])
        auc_scores.append(auc)

    # Rank features by t-statistic and AUC
    scores = [t * (auc - 0.5) for t, auc in zip(t_stats, auc_scores)]
    ranked_indices = np.argsort(scores)[::-1][:20]

    # Remove near-duplicates based on correlation
    keep_indices = []
    correlations = {}

    # Build correlation matrix for top features
    for i in range(len(ranked_indices)):
        idx1 = ranked_indices[i]
        fid1 = feats.ids[idx1]
        for j in range(i+1, len(ranked_indices)):
            idx2 = ranked_indices[j]
            fid2 = feats.ids[idx2]

            # Check if already computed
            if (fid1, fid2) in correlations or (fid2, fid1) in correlations:
                continue

            corr = np.corrcoef(feats.x[:, idx1], feats.x[:, idx2])[0, 1]
            correlations[(fid1, fid2)] = abs(corr)

            if abs(corr) >= 0.6:
                # Keep the one with higher score
                if scores[i] > scores[j]:
                    if idx1 not in keep_indices:
                        keep_indices.append(idx1)
                else:
                    if idx2 not in keep_indices:
                        keep_indices.append(idx2)
            else:
                if idx1 not in keep_indices:
                    keep_indices.append(idx1)
                if idx2 not in keep_indices:
                    keep_indices.append(idx2)

    # Ensure we don't exceed MAX_DRIVERS
    keep_indices = keep_indices[:MAX_DRIVERS]

    # If no strong signals, return empty design
    if not keep_indices:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select drivers based on highest scores
    drivers = [feats.ids[i] for i in keep_indices]

    # Select columns for regression
    columns = drivers[:]

    # Add interaction terms (products) for top features
    products = []
    for i in range(len(drivers)):
        for j in range(i+1, len(drivers)):
            products.append((drivers[i], drivers[j]))

    # Create weighted loading score
    loadings = {}
    for i, fid in enumerate(feats.ids):
        if fid in drivers:
            # Use standardized coefficient from simple logistic regression
            lr = LogisticRegression(penalty='l1', solver='liblinear', C=1.0)
            try:
                lr.fit(feats.x[:, [feats.column(fid)]], feats.y)
                loadings[fid] = abs(lr.coef_[0][0])
            except:
                loadings[fid] = 1.0

    # Limit to at most 4 drivers as per checker report
    if len(drivers) > 4:
        drivers = drivers[:4]
        columns = columns[:4]
        # Remove products involving excluded drivers
        products = [(a, b) for a, b in products if a in drivers and b in drivers]

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

